INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('efdc5802-4f68-43d3-9f1f-eb9849655b00', '8153806723826', '8153806723826', '2a63f47c-20ea-4e75-acb5-8852f7df958d', 'contact', '999274082385103407', 'Thế Anh Nvkd', '{"title":"\"Đơn hàng của anh chị đã được Viettel Post nhận hàng và trong quá trình vận chuyển đến. Vui lòng nhận hàng kiểm tra và thanh toán cho nhà giao vận. Em cảm ơn rất nhiều.\n\n✅HÓA ĐƠN: \n(Chưa bao gồm phí SHIP)\nPHÍ TÍNH THEO CÂN NẶNG NÊN KHI NHẬP KHO GIAO HÀNG BƯU CỤC SẼ THÔNG BÁO KHI KHÁCH NHẬN HÀNG\n\n✅THEO DÕI ĐƠN HÀNG: \nhttps://viettelpost.com.vn/\n\n✅NHẬP ĐƠN: PKE1495681523\nDâu rể thân mến,\nNếu bạn đặt thiệp vào lúc 4h chiều, thì từ 3h chúng mình đã bắt đầu vui sướng rồi.\nMỗi tấm thiệp trước khi gửi đi đều được Nhà Yến kiểm tra kỹ càng, nâng niu bọc gói, với hy vọng bạn không chỉ nhận được một tấm thiệp, mà còn nhận được cả niềm vui.\nTuy nhiên, nếu chẳng may có sơ suất, thì mong bạn đừng vội buồn, cũng đừng vội giận, hãy phản hồi qua inbox hoặc liên hệ hotline\n\nNếu tấm thiệp này đến với tay bạn đẹp đẽ, nguyên vẹn, rất mong bạn gửi feedbacks. Đó là động lực tinh thần để Nhà Yến phục vụ mọi Dâu Rể tốt hơn nữa.\n\nCảm ơn sự ủng hộ của bạn.\"","description":"Viettel Post","href":"https://viettelpost.com.vn/","thumb":"https://photo-link-talk.zadn.vn/photolinkv2/720/zlv24ca9230a9f1786755981aHR0cHM6Ly92aWV0dGVscG9zdC5jb20udm4vd3AtY29udGVudC91cGxvYWRzLzIwMjQvMTEvR3JvdXAtNTkzNC5wbmc=","childnumber":0,"action":"recommened.link","params":"{\"streamUrl\":\"\",\"mediaTitle\":\"Trang chủ\",\"stream_icon\":\"\",\"tType\":1,\"src\":\"viettelpost.com.vn\",\"artist\":\"\",\"tHeight\":247,\"type\":0,\"tWidth\":641}","type":""}', 'link', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T18:06:27.642Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('aec60495-6d6c-42bf-a339-d4b455234ab6', '8153806776630', '8153806776630', '2a63f47c-20ea-4e75-acb5-8852f7df958d', 'contact', '999274082385103407', 'Thế Anh Nvkd', 'Dạ mình nhận hàng thì hỗ trợ quay video lúc kiểm tra số lượng thiệp giúp em (vừa bỏ ruột thiệp vào bao vừa đếm), nếu có thiếu bên em sẽ in bù và gửi lại cho mình trong 4–5 ngày ạ, trường hợp bên em chưa kịp gửi thiệp video mà nhóm đã giải tán thì mình thông cảm giúp vì Zalo Business bên em bị giới hạn 2000 nhóm nên không tiếp nhận thêm được, anh chị vui lòng chủ động liên hệ lại để bên em gửi lại đúng như cam kết, cảm ơn anh chị rất nhiều ạ', 'text', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T18:06:28.996Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
