INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('af8faeb7-5dd2-4356-93dc-65bd22854687', '8153946230453', '8153946230453', 'c3783e50-e9aa-45a5-9837-281150f96511', 'contact', '999274082385103407', 'Thế Anh Nvkd', 'Dạ mình nhận hàng thì hỗ trợ quay video lúc kiểm tra số lượng thiệp giúp em (vừa bỏ ruột thiệp vào bao vừa đếm), nếu có thiếu bên em sẽ in bù và gửi lại cho mình trong 4–5 ngày ạ, trường hợp bên em chưa kịp gửi thiệp video mà nhóm đã giải tán thì mình thông cảm giúp vì Zalo Business bên em bị giới hạn 2000 nhóm nên không tiếp nhận thêm được, anh chị vui lòng chủ động liên hệ lại để bên em gửi lại đúng như cam kết, cảm ơn anh chị rất nhiều ạ', 'text', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T18:51:28.217Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
