INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('ce2025ff-1b4e-4add-b953-d50edafee35f', '8153960546615', '8153960546615', 'e95e4a01-e6b2-40db-aaca-5c52f8c280b0', 'contact', '4945063129019235665', 'Linh Thiệp Cưới', '{"title":"","description":"","href":"https://nhayencrm.com/files/media/0d1b2449d51a62fc68109291d7a3e793d7369049f10c0046dcb52a9c6b23f6c0.jpg","thumb":"https://nhayencrm.com/files/media/0d1b2449d51a62fc68109291d7a3e793d7369049f10c0046dcb52a9c6b23f6c0.jpg","childnumber":0,"action":"","params":"{\"id_in_group\":1,\"is_group_layout\":1,\"width\":1080,\"convertible\":\"jxl\",\"hd\":\"https://nhayencrm.com/files/media/0d1b2449d51a62fc68109291d7a3e793d7369049f10c0046dcb52a9c6b23f6c0.jpg\",\"group_layout_id\":1786758951425,\"height\":1440,\"total_item_in_group\":2}","type":""}', 'image', '[]'::jsonb, NULL, '1786758951425', 1, 2, '2026-08-14T18:55:51.724Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('823b5a8c-e1e1-4777-b97a-fc06bce6058b', '8153960800143', '8153960800143', 'e95e4a01-e6b2-40db-aaca-5c52f8c280b0', 'contact', '4945063129019235665', 'Linh Thiệp Cưới', '{"title":"Trong quá trình lên mẫu thiết kế, Nhà Yến kính mong Quý Anh Chị cùng phối hợp kiểm tra và phản hồi chi tiết để mẫu hoàn thiện đúng ý nhất trước khi chốt in.\nCác nội dung cần rà soát kỹ gồm:\n\n* Họ tên, địa chỉ, chức danh hai bên gia đình.\n* Thời gian và địa điểm làm lễ – đãi tiệc.\n* Năm âm lịch và dương lịch.\n* Màu sắc bao thư và ruột thiệp.\n* Các lỗi chính tả, dấu chấm, dấu phẩy, định dạng chữ.\n\nMọi yêu cầu hoặc góp ý chỉnh sửa, Quý Anh Chị vui lòng nhắn trực tiếp trong nhóm để đội ngũ Nhà Yến hỗ trợ nhanh nhất.\nBên em sẽ đồng hành cùng Anh Chị **đến khi thật sự ưng ý mới thôi** 💕\n\nHiện tại, bên em **hỗ trợ chỉnh sửa hoàn toàn miễn phí** trong suốt quá trình thiết kế.\nRiêng với những mẫu có nhiều yêu cầu sáng tạo, thay đổi bố cục hoặc phong cách ** so với bản gốc**, bên em xin phép **phụ thu thêm 300.000đ phí thiết kế** để đảm bảo chất lượng và tiến độ tốt nhất. Rất mong Quý Anh Chị thông cảm và cùng phối hợp để có được **mẫu thiệp thật đẹp và ý nghĩa nhất** ạ.\n\nSau khi chốt in, **Nhà Yến sẽ gửi tặng Quý Anh Chị một video thiệp cưới online** (phù hợp để đăng Story, Reel Facebook hoặc TikTok).\n\nTrong trường hợp cần hỗ trợ gấp, Quý Anh Chị có thể liên hệ trực tiếp qua hotline:\n☎ 0913 980 993 (Hỗ trợ khách hàng)**\n\n**Thời gian làm việc:**\n\n* Thứ Hai – Thứ Bảy\n* Sáng: 7h30 – 11h30\n* Chiều: 13h30 – 17h30\n\nTrân trọng cảm ơn Quý Anh Chị đã tin tưởng và đồng hành cùng **Thiệp Cưới Nhà Yến** 💌 @Phương Thanh","description":"","href":"https://nhayencrm.com/files/media/d77772a23deed97bdaacc7cb98fad64e6ca73e68c0d0668e1830784f986157e7.jpg","thumb":"https://nhayencrm.com/files/media/d77772a23deed97bdaacc7cb98fad64e6ca73e68c0d0668e1830784f986157e7.jpg","childnumber":0,"action":"","params":"{\"is_original\":1,\"width\":1200,\"hd\":\"https://nhayencrm.com/files/media/d77772a23deed97bdaacc7cb98fad64e6ca73e68c0d0668e1830784f986157e7.jpg\",\"height\":675}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T18:55:56.265Z', NULL, NULL, NULL, 'user', false, NULL, '[{"len":13,"pos":1410,"uid":"5536747351140647719","type":0}]'::jsonb) ON CONFLICT (id) DO NOTHING;
