INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('3e2e57d2-e1eb-4655-afbf-8a58d0f7ef24', '8154038300584', '8154038300584', 'efbf4ad0-193a-4af9-9928-cdfbd9647a45', 'contact', '4637711696281257389', 'Khang Thiệp Cưới', '{"title":"Em gửi bill chưa bao gồm phí vận chuyển ạ! Vì đơn hàng cần được cân lên mới có giá chính xác do bên giao hàng đảm nhận. Mình yên tâm khi đơn hoàn thành tất cả các khâu ở group này sẽ có mã vận đơn để mình tiện theo dõi ạ!\n\n Dạ thời gian in ấn và giao hàng bên em khoảng 8 - 10 ngày sau ngày chốt file in, không tính chủ nhật ạ","description":"","href":"https://nhayencrm.com/files/media/c6bc9afd54a188788d4380686820d81493c52acb77395aaa6b48941ccc41d560.jpg","thumb":"https://nhayencrm.com/files/media/c6bc9afd54a188788d4380686820d81493c52acb77395aaa6b48941ccc41d560.jpg","childnumber":0,"action":"","params":"{\"width\":918,\"convertible\":\"jxl\",\"hd\":\"https://nhayencrm.com/files/media/c6bc9afd54a188788d4380686820d81493c52acb77395aaa6b48941ccc41d560.jpg\",\"height\":578}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T19:16:27.940Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('b42a9ddb-bbaf-42f1-8e15-9fe46d5bd8bf', '8154038564776', '8154038564776', 'efbf4ad0-193a-4af9-9928-cdfbd9647a45', 'contact', '4637711696281257389', 'Khang Thiệp Cưới', '{"title":"Trước tiên, bên em chân thành cảm ơn Quý Khách đã tin tưởng và lựa chọn sản phẩm/dịch vụ của chúng tôi. Theo chính sách của Công ty, đối với các đơn hàng trên 1,5 triệu đồng,  mong Quý Khách có thể hỗ trợ đặt cọc một số tiền nhỏ trước khi mua hàng là 500.000đ để đảm bảo quá trình đặt hàng và giao nhận được diễn ra suôn sẻ và nhanh chóng. Khoản đặt cọc này sẽ giúp công ty xác nhận đơn hàng của mình và chuẩn bị sản phẩm một cách chu đáo nhất. Bên em cam kết khoản tiền đặt cọc sẽ được trừ trực tiếp vào tổng giá trị đơn hàng khi nhận hàng.\n\nSau khi chuyển khoản, anh chị gửi hóa đơn chuyển khoản vào nhóm cho bộ phận kế toán của bên em ghi nhận trừ vào hoá đơn ạ \n\nThông tin chuyển khoản:\n\n✅ Ngân hàng: Techcombank\n\n✅ Số tài khoản: MS04T11750128362636\n\n✅ Tên tài khoản: CONG TY TNHH THIEP CUOI NHA YEN CANARY\n\n✅ Số tiền: 500.000 đồng\n\n✅ Nội dung chuyển khoản: MÃ NHÓM ZALO (VD: D010101)\n\nEm cảm ơn sự hợp tác và tin tưởng của mình","description":"","href":"https://nhayencrm.com/files/media/dabb65eb53cb3e5e86771a91a4ad47e20f8fdf81d82d397482ba96c2f562755b.jpg","thumb":"https://nhayencrm.com/files/media/dabb65eb53cb3e5e86771a91a4ad47e20f8fdf81d82d397482ba96c2f562755b.jpg","childnumber":0,"action":"","params":"{\"width\":1451,\"convertible\":\"jxl\",\"hd\":\"https://nhayencrm.com/files/media/dabb65eb53cb3e5e86771a91a4ad47e20f8fdf81d82d397482ba96c2f562755b.jpg\",\"height\":1584}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T19:16:31.722Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
