INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('b70de19f-313c-4d54-8035-e12302acca9e', '8154141083077', '8154141083077', '03fe02b2-aafe-4919-bc2b-4cf5f71e9df4', 'self', '419868129653264162', 'Staff', 'Em tạo nhóm để các bạn thiết kế gửi demo thiệp trực tiếp cho mình xem và góp ý chỉnh sửa nha. Mình có thể thêm người thân hoặc bạn bè vào nhóm để cùng xem và kiểm tra cho yên tâm hơn. Trong quá trình chỉnh sửa, mình cứ nhắn trực tiếp trong nhóm giúp em, bên em sẽ hỗ trợ tận tình đến khi nào mình ưng mới thôi nên mình đừng ngại góp ý gì hết nha. Riêng với những mẫu có nhiều yêu cầu sáng tạo hoặc thay đổi bố cục, mix mẫu, thay đổi phong cách so với bản gốc, bên em xin phép phụ thu thêm phí thiết kế 300.000đ - 500.000đ để đảm bảo chất lượng và tiến độ tốt nhất ạ. Hiện bên em đang vào mùa cưới cao điểm nên thời gian gửi demo dự kiến trong 3-4 ngày, có thể sớm hơn nếu trống lịch thiết kế. Mong mình thông cảm và cùng bên em phối hợp để có được mẫu thiệp thật đẹp và ý nghĩa nhất nha. Em cảm ơn ạ', 'text', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T19:41:52.467Z', '2026-08-14T19:41:52.990Z', NULL, 'cfe210ab-2b34-47b7-8d9a-7cdf8364c07a', 'user', false, '{"sender":{"kind":"user_crm","name":"thaophamce"}}'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
