INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('8e25d6f0-5c3c-4e64-9de7-322466e54cbe', '8154147041536', '8154147041536', '4a1e17a9-35de-4af6-95ea-8c5f87fa76e7', 'contact', '4637711696281257389', 'Khang Thiệp Cưới', '{"title":"***PHÍ IN LẠI/IN PHÁT SINH\n📌  Bao thư: 3.000đ/bao thư (tối thiểu 50)\n📌  Ruột lẻ: 3.000đ/1 tờ (tối thiểu 50)\nIn phát sinh 50-149 thiệp: 8.000đ/bộ\n⚠ ⚠ DÂU RỂ CÂN NHẮC KIỂM TRA KỸ TRÁNH IN PHÁT SINH THÊM VÌ SAU NÀY IN GIÁ CAO VÀ THỜI GIAN NHẬN LÂU\n\n⛔ MÀU SẮC IN THÀNH PHẨM CHỈ ĐẠT 95% TƯƠNG ĐỐI SO VỚI MÀN HÌNH (vì màu sắc xem trên Ipad, Iphone, Samsung, PC,...tất cả sẽ khác nhau)\n⛔ CÙNG 1 FILE IN, SAU MỖI LẦN IN SẼ KHÁC NHAU (có sự chênh lệch màu đậm/nhạt hơn).\n⛔ TRONG CÙNG 1 KIỆN HÀNG, ĐẶC BIỆT VỚI NHŨNG FILE CÓ NỀN MÀU SẬM THÌ ĐỘ ĐỒNG ĐỀU VỀ MÀU SẮC LÀ TƯƠNG ĐỐI.\n⛔ GIẤY ÁNH NHŨ KHI IN NỀN MÀU ĐẬM SẼ KHÔNG RÕ ÁNH NHŨ BẰNG NỀN MÀU NHẠT.\n\nKhi nào nhận hàng anh chị vui lòng kiểm tra và thanh toán COD giùm em. Vui lòng cho em xin thông tin nhận hàng: Tên/SĐT/Địa chỉ. Em cảm ơn ạ","description":"","href":"https://nhayencrm.com/files/media/6242cb4ae5572a9dc74f789ed2ec0ba00f857adcf3d701092c4137432580c5ba.jpg","thumb":"https://nhayencrm.com/files/media/6242cb4ae5572a9dc74f789ed2ec0ba00f857adcf3d701092c4137432580c5ba.jpg","childnumber":0,"action":"","params":"{\"width\":1412,\"convertible\":\"jxl\",\"hd\":\"https://nhayencrm.com/files/media/6242cb4ae5572a9dc74f789ed2ec0ba00f857adcf3d701092c4137432580c5ba.jpg\",\"height\":2000}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T19:43:21.753Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
