INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('26f9e326-3eac-4eb0-89e3-0ec1ca09cf02', '8154328914881', '8154328914881', '6b532b18-76bf-4815-a255-eae20a3d5074', 'contact', '4637711696281257389', 'Khang Thiệp Cưới', '{"title":"Trước tiên, bên em chân thành cảm ơn Quý Khách đã tin tưởng và lựa chọn sản phẩm/dịch vụ của chúng tôi. Theo chính sách của Công ty, đối với các đơn hàng trên 3 triệu đồng,  mong Quý Khách có thể hỗ trợ đặt cọc một số tiền nhỏ trước khi mua hàng là 1.000.000đ để đảm bảo quá trình đặt hàng và giao nhận được diễn ra suôn sẻ và nhanh chóng. Khoản đặt cọc này sẽ giúp công ty xác nhận đơn hàng của mình và chuẩn bị sản phẩm một cách chu đáo nhất. Bên em cam kết khoản tiền đặt cọc sẽ được trừ trực tiếp vào tổng giá trị đơn hàng khi nhận hàng.\n\nSau khi chuyển khoản, anh chị gửi hóa đơn chuyển khoản vào nhóm cho bộ phận kế toán của bên em ghi nhận trừ vào hoá đơn ạ \n\nThông tin chuyển khoản:\n\n✅ Ngân hàng: Techcombank\n\n✅ Số tài khoản: MS04T11750128362636\n\n✅ Tên tài khoản: CONG TY TNHH THIEP CUOI NHA YEN CANARY\n\n✅ Số tiền: 1.000.000 đồng\n\n✅ Nội dung chuyển khoản: MÃ NHÓM ZALO (VD: D010101)\n\nEm cảm ơn sự hợp tác và tin tưởng của mình","description":"","href":"https://nhayencrm.com/files/media/dabb65eb53cb3e5e86771a91a4ad47e20f8fdf81d82d397482ba96c2f562755b.jpg","thumb":"https://nhayencrm.com/files/media/dabb65eb53cb3e5e86771a91a4ad47e20f8fdf81d82d397482ba96c2f562755b.jpg","childnumber":0,"action":"","params":"{\"width\":1451,\"convertible\":\"jxl\",\"hd\":\"https://nhayencrm.com/files/media/dabb65eb53cb3e5e86771a91a4ad47e20f8fdf81d82d397482ba96c2f562755b.jpg\",\"height\":1584}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T20:26:40.399Z', NULL, NULL, NULL, 'user', false, NULL, 