INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('114d9b1c-a95e-450d-9b0d-fe227d401670', '8154340798505', '8154340798505', 'c7e08955-ff93-4380-acda-28b16ef3e4df', 'contact', '4637711696281257389', 'Khang Thiệp Cưới', '{"title":"📌 TUỲ CHỌN NHẬN HÀNG:\n\n✅ IN HOẢ TỐC: 2-3 ngày – Phụ phí 500.000đ (Chỉ áp dụng mẫu phôi)\n(TP.HCM có thể nhận trong ngày)\n\n✅ IN NHANH: 4-5 ngày – Phụ phí 300.000đ \n(Ưu tiên ship chành xe) \n(Phí in nhanh chưa bao gồm phí ship.)\n\n✅ IN TIẾT KIỆM: 5-7 ngày (Khuyên chọn)\nKhông tính Chủ Nhật\n\n💡 Công ty sẽ cố gắng áp dụng phương thức vận chuyển nhanh nhất để đảm bảo tiến độ. Nếu không kịp, phí in nhanh sẽ được hoàn lại.\n\nDạ mình chọn option nào báo bên em triển khai các phương án để kịp tiến độ giao nhận nha\n\n***PHÍ IN LẠI/IN PHÁT SINH\n📌  Bao thư: 3.000đ/bao thư (tối thiểu 50)\n📌  Ruột lẻ: 3.000đ/1 tờ (tối thiểu 50)\nIn phát sinh 50-149 thiệp: 8.000đ/bộ\n⚠ ⚠ DÂU RỂ CÂN NHẮC KIỂM TRA KỸ TRÁNH IN PHÁT SINH THÊM VÌ SAU NÀY IN GIÁ CAO VÀ THỜI GIAN NHẬN LÂU\n\n⛔ MÀU SẮC IN THÀNH PHẨM CHỈ ĐẠT 95% TƯƠNG ĐỐI SO VỚI MÀN HÌNH (vì màu sắc xem trên Ipad, Iphone, Samsung, PC,...tất cả sẽ khác nhau)\n⛔ CÙNG 1 FILE IN, SAU MỖI LẦN IN SẼ KHÁC NHAU (có sự chênh lệch màu đậm/nhạt hơn).\n⛔ TRONG CÙNG 1 KIỆN HÀNG, ĐẶC BIỆT VỚI NHŨNG FILE CÓ NỀN MÀU SẬM THÌ ĐỘ ĐỒNG ĐỀU VỀ MÀU SẮC LÀ TƯƠNG ĐỐI.\n⛔ GIẤY ÁNH NHŨ KHI IN NỀN MÀU ĐẬM SẼ KHÔNG RÕ ÁNH NHŨ BẰNG NỀN MÀU NHẠT.\n\nKhi nào nhận hàng anh chị vui lòng kiểm tra và thanh toán COD giùm em. Vui lòng cho em xin thông tin nhận hàng: Tên/SĐT/Địa chỉ. Em cảm ơn ạ","description":"","href":"https://nhayencrm.com/files/media/6242cb4ae5572a9dc74f789ed2ec0ba00f857adcf3d701092c4137432580c5ba.jpg","thumb":"https://nhayencrm.com/files/media/6242cb4ae5572a9dc74f789ed2ec0ba00f857adcf3d701092c4137432580c5ba.jpg","childnumber":0,"action":"","params":"{\"width\":1412,\"convertible\":\"jxl\",\"hd\":\"https://nhayencrm.com/files/media/6242cb4ae5572a9dc74f789ed2ec0ba00f857adcf3d701092c4137432580c5ba.jpg\",\"height\":2000}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T20:29:28.145Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
