INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('aa384358-ef68-4fc6-a286-8b2914423c63', '8154416340134', '8154416340134', '4e698e31-e9c1-4e0f-bb1c-c36be82878f8', 'contact', '4945063129019235665', 'Linh Thiệp Cưới', '{"title":"Em gửi bill chưa bao gồm phí vận chuyển ạ! Vì đơn hàng cần được cân lên mới có giá chính xác do bên giao hàng đảm nhận. Mình yên tâm khi đơn hoàn thành tất cả các khâu ở group này sẽ có mã vận đơn để mình tiện theo dõi ạ!\nDạ thời gian in ấn và giao hàng bên em khoảng 5 - 7 ngày sau ngày chốt file ( in từ ngày tiếp theo), không tính Chủ nhật","description":"","href":"https://nhayencrm.com/files/media/553000a44d95bff364a6bf1d17ed6d48ba884df887bb2a8b95b2fc4aad00d2e7.jpg","thumb":"https://nhayencrm.com/files/media/553000a44d95bff364a6bf1d17ed6d48ba884df887bb2a8b95b2fc4aad00d2e7.jpg","childnumber":0,"action":"","params":"{\"is_original\":1,\"width\":842,\"hd\":\"https://nhayencrm.com/files/media/553000a44d95bff364a6bf1d17ed6d48ba884df887bb2a8b95b2fc4aad00d2e7.jpg\",\"height\":318}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T20:47:06.583Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('ef2f7c5f-c70d-4f40-9b0b-b5ecd278af9c', '8154416485129', '8154416485129', '4e698e31-e9c1-4e0f-bb1c-c36be82878f8', 'contact', '4945063129019235665', 'Linh Thiệp Cưới', '{"title":"Dạ em xin phép nhắc lại rằng: sau khi file được anh/chị xác nhận “CHỐT IN”, bên em sẽ tiến hành IN ĐÚNG THEO NỘI DUNG LÀ FILE CUỐI CÙNG NÀY và KHÔNG CHỊU TRÁCH NHIỆM nếu có sai sót về thông tin.\nDo số lượng đơn hàng lớn, để hạn chế sai sót tối đa, bên em kính mong Quý khách dành ít phút đồng kiểm tra lại toàn bộ thông tin trên file final (họ tên, ba mẹ, CDCR, ngày giờ, địa điểm, chính tả) trước khi duyệt in.\nSau khi Quý khách xác nhận duyệt in, bên em sẽ tiến hành sản xuất theo nội dung đã duyệt và không thể chỉnh sửa hoặc chịu trách nhiệm với các sai sót về nội dung.\nRất mong quý anh/chị kiểm tra kỹ trước khi xác nhận. Em xin cảm ơn rất nhiều ạ!\n\n***PHÍ IN LẠI/IN PHÁT SINH\n📌  Bao thư: 3.000đ/bao thư (tối thiểu 50)\n📌  Ruột lẻ: 3.000đ/1 tờ (tối thiểu 50)\nIn phát sinh 50-149 thiệp: 9.000đ/bộ\n⚠ ⚠ DÂU RỂ CÂN NHẮC KIỂM TRA KỸ TRÁNH IN PHÁT SINH THÊM VÌ SAU NÀY IN GIÁ CAO VÀ THỜI GIAN NHẬN LÂU\n\n\n⛔ MÀU SẮC IN THÀNH PHẨM CHỈ ĐẠT 95% TƯƠNG ĐỐI SO VỚI MÀN HÌNH (vì màu sắc xem trên Ipad, Iphone, Samsung, PC,...tất cả sẽ khác nhau)\n⛔ CÙNG 1 FILE IN, SAU MỖI LẦN IN SẼ KHÁC NHAU (có sự chênh lệch màu đậm/nhạt hơn). \n⛔ TRONG CÙNG 1 KIỆN HÀNG, ĐẶC BIỆT VỚI NHŨNG FILE CÓ NỀN MÀU SẬM THÌ ĐỘ ĐỒNG ĐỀU VỀ MÀU SẮC LÀ TƯƠNG ĐỐI. \n⛔ GIẤY ÁNH NHŨ KHI IN NỀN MÀU ĐẬM SẼ KHÔNG RÕ ÁNH NHŨ BẰNG NỀN MÀU NHẠT.","description":"","href":"https://nhayencrm.com/files/media/c602d97a92f44b2d436c3c68df448a62844aa33f4ccd432aa5a83669bfe213de.jpg","thumb":"https://nhayencrm.com/files/media/c602d97a92f44b2d436c3c68df448a62844aa33f4ccd432aa5a83669bfe213de.jpg","childnumber":0,"action":"","params":"{\"is_original\":1,\"width\":1412,\"hd\":\"https://nhayencrm.com/files/media/c602d97a92f44b2d436c3c68df448a62844aa33f4ccd432aa5a83669bfe213de.jpg\",\"height\":2000}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T20:47:08.629Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('78a2b283-82dc-416a-8ccc-81ee2ecc1f23', '8154416831376', '8154416831376', '4e698e31-e9c1-4e0f-bb1c-c36be82878f8', 'contact', '4945063129019235665', 'Linh Thiệp Cưới', '@Như Như Nếu mọi thông tin đã hoàn toàn chính xác, anh/chị vui lòng nhắn tin xác nhận giúp em cú pháp: ''DUYỆT IN'' để em chuyển đơn sang xưởng chạy máy in.
