INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('59d83939-e22c-47a2-a0d2-bc69fc1fd51f', '8154431169532', '8154431169532', '621b6d25-cafa-4a23-956b-bd48cf9ff276', 'contact', '4637711696281257389', 'Khang Thiệp Cưới', 'Thay mặt Thiệp cưới Nhà Yến, em cảm ơn anh chị đã tin tưởng lựa chọn dịch vụ của bên em, xin chúc anh chị trăm năm hạnh phúc, sớm đón tin vui và luôn thuận buồm xuôi gió trong mọi dự định tương lai; hành trình hôn nhân mong rằng sẽ luôn ngập tràn yêu thương qua từng mùa xuân, hạ, thu, đông và cùng nhau già đi trong tình yêu, thương thương /-heart /-heart /-heart /-heart /-heart /-heart
