INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('04062105-6246-4ba5-be82-cf05e489de57', '8154433463403', '8154433463403', 'fff0f58f-528d-4b1b-a8b5-1ed5dba02011', 'contact', '4945063129019235665', 'Linh Thiệp Cưới', '{"title":"Em gửi bill chưa bao gồm phí vận chuyển ạ! Vì đơn hàng cần được cân lên mới có giá chính xác do bên giao hàng đảm nhận. Mình yên tâm khi đơn hoàn thành tất cả các khâu ở group này sẽ có mã vận đơn để mình tiện theo dõi ạ!\nDạ thời gian in ấn và giao hàng bên em khoảng 5 - 7 ngày sau ngày chốt file ( in từ ngày tiếp theo), không tính Chủ nhật","description":"","href":"https://nhayencrm.com/files/media/66dd03185c0153fe39094ad58639d34d369df4affd2c02bae689e0a7409d82c7.jpg","thumb":"https://nhayencrm.com/files/media/66dd03185c0153fe39094ad58639d34d369df4affd2c02bae689e0a7409d82c7.jpg","childnumber":0,"action":"","params":"{\"is_original\":1,\"width\":845,\"hd\":\"https://nhayencrm.com/files/media/66dd03185c0153fe39094ad58639d34d369df4affd2c02bae689e0a7409d82c7.jpg\",\"height\":321}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T20:51:06.904Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
