INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('c1e6d2b3-a619-466f-a61c-326721acc401', '8154434226243', '8154434226243', 'fff0f58f-528d-4b1b-a8b5-1ed5dba02011', 'contact', '4945063129019235665', 'Linh Thiệp Cưới', '{"title":"Dạ em xin phép nhắc lại rằng: sau khi file được anh/chị xác nhận “CHỐT IN”, bên em sẽ tiến hành IN ĐÚNG THEO NỘI DUNG LÀ FILE CUỐI CÙNG NÀY và KHÔNG CHỊU TRÁCH NHIỆM nếu có sai sót về thông tin.\nDo số lượng đơn hàng lớn, để hạn chế sai sót tối đa, bên em kính mong Quý khách dành ít phút đồng kiểm tra lại toàn bộ thông tin trên file final (họ tên, ba mẹ, CDCR, ngày giờ, địa điểm, chính tả) trước khi duyệt in.\nSau khi Quý khách xác nhận duyệt in, bên em sẽ tiến hành sản xuất theo nội dung đã duyệt và không thể chỉnh sửa hoặc chịu trách nhiệm với các sai sót về nội dung.\nRất mong quý anh/chị kiểm tra kỹ trước khi xác nhận. Em xin cảm ơn rất nhiều ạ!\n\n***PHÍ IN LẠI/IN PHÁT SINH\n📌  Bao thư: 3.000đ/bao thư (tối thiểu 50)\n📌  Ruột lẻ: 3.000đ/1 tờ (tối thiểu 50)\nIn phát sinh 50-149 thiệp: 9.000đ/bộ\n⚠ ⚠ DÂU RỂ CÂN NHẮC KIỂM TRA KỸ TRÁNH IN PHÁT SINH THÊM VÌ SAU NÀY IN GIÁ CAO VÀ THỜI GIAN NHẬN LÂU\n\n\n⛔ MÀU SẮC IN THÀNH PHẨM CHỈ ĐẠT 95% TƯƠNG ĐỐI SO VỚI MÀN HÌNH (vì màu sắc xem trên Ipad, Iphone, Samsung, PC,...tất cả sẽ khác nhau)\n⛔ CÙNG 1 FILE IN, SAU MỖI LẦN IN SẼ KHÁC NHAU (có sự chênh lệch màu đậm/nhạt hơn). \n⛔ TRONG CÙNG 1 KIỆN HÀNG, ĐẶC BIỆT VỚI NHŨNG FILE CÓ NỀN MÀU SẬM THÌ ĐỘ ĐỒNG ĐỀU VỀ MÀU SẮC LÀ TƯƠNG ĐỐI. \n⛔ GIẤY ÁNH NHŨ KHI IN NỀN MÀU ĐẬM SẼ KHÔNG RÕ ÁNH NHŨ BẰNG NỀN MÀU NHẠT.","description":"","href":"https://nhayencrm.com/files/media/c602d97a92f44b2d436c3c68df448a62844aa33f4ccd432aa5a83669bfe213de.jpg","thumb":"https://nhayencrm.com/files/media/c602d97a92f44b2d436c3c68df448a62844aa33f4ccd432aa5a83669bfe213de.jpg","childnumber":0,"action":"","params":"{\"is_original\":1,\"width\":1412,\"hd\":\"https://nhayencrm.com/files/media/c602d97a92f44b2d436c3c68df448a62844aa33f4ccd432aa5a83669bfe213de.jpg\",\"height\":2000}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T20:51:17.586Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('064d1390-2c42-4ac1-ade7-f77eff359b66', '8154435026882', '8154435026882', 'fff0f58f-528d-4b1b-a8b5-1ed5dba02011', 'contact', '4945063129019235665', 'Linh Thiệp Cưới', '{"title":"Trước tiên, bên em chân thành cảm ơn Quý Khách đã tin tưởng và lựa chọn sản phẩm/dịch vụ của chúng tôi. Theo chính sách của Công ty, đối với các đơn hàng trên 1,5 triệu đồng,  mong Quý Khách có thể hỗ trợ đặt cọc một số tiền nhỏ trước khi mua hàng là 500.000đ để đảm bảo quá trình đặt hàng và giao nhận được diễn ra suôn sẻ và nhanh chóng. Khoản đặt cọc này sẽ giúp công ty xác nhận đơn hàng của mình và chuẩn bị sản phẩm một cách chu đáo nhất. Bên em cam kết khoản tiền đặt cọc sẽ được trừ trực tiếp vào tổng giá trị đơn hàng khi nhận hàng.\n\nSau khi chuyển khoản, anh chị gửi hóa đơn chuyển khoản vào nhóm cho bộ phận kế toán của bên em ghi nhận trừ vào hoá đơn ạ \n\nThông tin chuyển khoản:\n\n✅ Ngân hàng: Techcombank\n\n✅ Số tài khoản: MS04T11750128362636\n\n✅ Tên tài khoản: CONG TY TNHH THIEP CUOI NHA YEN CANARY\n\n✅ Số tiền: 500.000 đồng\n\n✅ Nội dung chuyển khoản: MÃ NHÓM ZALO (VD: D010101)\n\nEm cảm ơn sự hợp tác và tin tưởng của mình","description":"","href":"https://nhayencrm.com/files/media/08d266b6f83e7dd13650a1b6954ffe0ea1d28ed2d357a485363111305426caf0.jpg","thumb":"https://nhayencrm.com/files/media/08d266b6f83e7dd13650a1b6954ffe0ea1d28ed2d357a485363111305426caf0.jpg","childnumber":0,"action":"","params":"{\"is_original\":1,\"width\":1451,\"hd\":\"https://nhayencrm.com/files/media/08d266b6f83e7dd13650a1b6954ffe0ea1d28ed2d357a485363111305426caf0.jpg\",\"height\":1584}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T20:51:28.754Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
