INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('3afe452a-b5b6-46e6-9ec0-85d77c6aef1f', '8154451846684', '8154451846684', 'ec5032ce-1397-402b-ba1c-a3c7136f21cf', 'contact', '4945063129019235665', 'Linh Thiệp Cưới', '{"title":"Trước tiên, bên em chân thành cảm ơn Quý Khách đã tin tưởng và lựa chọn sản phẩm/dịch vụ của chúng tôi. Theo chính sách của Công ty, đối với các đơn hàng trên 1,5 triệu đồng,  mong Quý Khách có thể hỗ trợ đặt cọc một số tiền nhỏ trước khi mua hàng là 500.000đ để đảm bảo quá trình đặt hàng và giao nhận được diễn ra suôn sẻ và nhanh chóng. Khoản đặt cọc này sẽ giúp công ty xác nhận đơn hàng của mình và chuẩn bị sản phẩm một cách chu đáo nhất. Bên em cam kết khoản tiền đặt cọc sẽ được trừ trực tiếp vào tổng giá trị đơn hàng khi nhận hàng.\n\nSau khi chuyển khoản, anh chị gửi hóa đơn chuyển khoản vào nhóm cho bộ phận kế toán của bên em ghi nhận trừ vào hoá đơn ạ \n\nThông tin chuyển khoản:\n\n✅ Ngân hàng: Techcombank\n\n✅ Số tài khoản: MS04T11750128362636\n\n✅ Tên tài khoản: CONG TY TNHH THIEP CUOI NHA YEN CANARY\n\n✅ Số tiền: 500.000 đồng\n\n✅ Nội dung chuyển khoản: MÃ NHÓM ZALO (VD: D010101)\n\nEm cảm ơn sự hợp tác và tin tưởng của mình","description":"","href":"https://nhayencrm.com/files/media/08d266b6f83e7dd13650a1b6954ffe0ea1d28ed2d357a485363111305426caf0.jpg","thumb":"https://nhayencrm.com/files/media/08d266b6f83e7dd13650a1b6954ffe0ea1d28ed2d357a485363111305426caf0.jpg","childnumber":0,"action":"","params":"{\"is_original\":1,\"width\":1451,\"hd\":\"https://nhayencrm.com/files/media/08d266b6f83e7dd13650a1b6954ffe0ea1d28ed2d357a485363111305426caf0.jpg\",\"height\":1584}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T20:55:25.153Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
