INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('e20f907b-346f-4a08-91c7-03df274bca04', '8154483948803', '8154483948803', 'ac22965d-2e28-47c0-9474-e4697caf3664', 'contact', '5287216819773689774', 'Quang Vĩ Tần', '@Khang Thiệp Cưới giờ mình sẽ ck cọc 500k trước cho anh phải ko', 'text', '[]'::jsonb, '{"ts":1786755426047,"msg":"","ttl":0,"fromD":"Khang Thiệp Cưới","attach":"{\"msgBubbleLayoutType\":1,\"title\":\"Trước tiên, bên em chân thành cảm ơn Quý Khách đã tin tưởng và lựa chọn sản phẩm\\/dịch vụ của chúng tôi. Theo chính sách của Công ty, đối với các đơn hàng trên 1,5 triệu đồng,  mong Quý Khách có thể hỗ trợ đặt cọc một số tiền nhỏ trước khi mua hàng là 500.000đ để đảm bảo quá trình đặt hàng và giao nhận được diễn ra suôn sẻ và nhanh chóng. Khoản đặt cọc này sẽ giúp công ty xác nhận đơn hàng của mình và chuẩn bị sản phẩm một cách chu đáo nhất. Bên em cam kết khoản tiền đặt cọc sẽ được trừ trực tiếp vào tổng giá trị đơn hàng khi nhận hàng.\\n\\nSau khi chuyển khoản, anh chị gửi hóa đơn chuyển khoản vào nhóm cho bộ phận kế toán của bên em ghi nhận trừ vào hoá đơn ạ \\n\\nThông tin chuyển khoản:\\n\\n✅ Ngân hàng: Techcombank\\n\\n✅ Số tài khoản: MS04T11750128362636\\n\\n✅ Tên tài khoản: CONG TY TNHH THIEP CUOI NHA YEN CANARY\\n\\n✅ Số tiền: 500.000 đồng\\n\\n✅ Nội dung chuyển khoản: MÃ NHÓM ZALO (VD: D010101)\\n\\nEm cảm ơn sự hợp tác và tin tưởng của mình\",\"thumb\":\"https:\\/\\/photo-stal-35.zdn.vn\\/gr\\/jpg\\/767922ba51f788a9d1e6\\/2aOboQrbLIL6Jh5kD2IGi68YMSlhyXgaULOzajxI.jpg\",\"href\":\"https:\\/\\/photo-stal-35.zdn.vn\\/gr\\/jpg\\/767922ba51f788a9d1e6\\/2aOboQrbLIL6Jh5kD2IGi68YMSlhyXgaULOzajxI.jpg\",\"params\":\"{\\\"convertible\\\":\\\"jxl\\\",\\\"tracking\\\":{\\\"subsource\\\":\\\"0\\\",\\\"source\\\":0},\\\"width