INSERT INTO messages (id, zalo_msg_id, zalo_msg_id_num, conversation_id, sender_type, sender_uid, sender_name, content, content_type, attachments, quote, album_key, album_index, album_total, sent_at, delivered_at, seen_at, replied_by_user_id, sent_via, is_local, metadata, mentions) VALUES ('c2aac926-4f06-4d01-90ac-cbb336c3b534', '8154486429589', '8154486429589', 'e48c2ebe-2918-4dfd-8a86-f5ab5a8f1171', 'contact', '4637711696281257389', 'Khang Thiệp Cưới', '{"title":"Dạ mình nhận được một video thiệp cưới online miễn phí từ Nhà Yến. Mình có thể chọn một trong ba mẫu tại trang web:\nhttps://www.thiepcuoinhayen.com/thieponline\n\nAnh/chị chọn mẫu 1 (gửi 4 ảnh cưới), mẫu 3 (gửi 6 ảnh cưới). Thời gian lên demo video là 2-3 ngày ạ.\n\nEm xin chia sẻ thêm, hiện nay có khá nhiều trường hợp lừa đảo qua link và mã QR, nên đa số khách hàng bên em ưu tiên sử dụng thiệp video để gửi trực tiếp cho khách mời qua Zalo/Facebook hoặc đăng lên TikTok, Facebook – vừa an toàn, vừa thuận tiện và sang trọng hơn ạ. Mình có nhu cầu tạo thiệp cưới dạng website truy cập cinelove.me hiện tại đang miễn phí và nhiều mẫu đẹp ạ.","description":"","href":"https://nhayencrm.com/files/media/cf60049ef791a7478ee28ac4b158c6dc7db0e96e67336218b405fd93a392879f.jpg","thumb":"https://nhayencrm.com/files/media/cf60049ef791a7478ee28ac4b158c6dc7db0e96e67336218b405fd93a392879f.jpg","childnumber":0,"action":"","params":"{\"width\":1302,\"convertible\":\"jxl\",\"hd\":\"https://nhayencrm.com/files/media/cf60049ef791a7478ee28ac4b158c6dc7db0e96e67336218b405fd93a392879f.jpg\",\"height\":999}","type":""}', 'image', '[]'::jsonb, NULL, NULL, NULL, NULL, '2026-08-14T21:03:30.477Z', NULL, NULL, NULL, 'user', false, NULL, NULL) ON CONFLICT (id) DO NOTHING;
